onHeadersComplete(mailChannel) {
  if (!this._channelIsCurrent(mailChannel)) {
    return;
  }
  window.msgLoading = true;
  window.dispatchEvent(
    new CustomEvent("MsgLoading", { detail: gMessage, bubbles: true })
  );

  getMessagePaneBrowser().addEventListener(
    "DOMContentLoaded",
    event => this.onDOMContentLoaded(event),
    { once: true }
  );
  this.processHeaders(mailChannel.headerNames, mailChannel.headerValues);
},

/**
 * Step 3: The parser has finished reading the body of the message.
 *
 * @param {nsIMailChannel} mailChannel
 * @see {nsIMailProgressListener}
 */
onBodyComplete(mailChannel) {
  if (!this._channelIsCurrent(mailChannel)) {
    return;
  }

  if (
    mailChannel.URI instanceof Ci.nsIMsgMailNewsUrl &&
    mailChannel.URI.errorCode
  ) {
    // This appears to be an NNTP message that couldn't be successfully
    // retrieved from the server.
    return;
  }

  autoMarkAsRead();
},

